head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > initValue]<br/>컴포넌트가 렌더링 시 입력값으로 설정될 초기값을 설정합니다.",
    "validation" : [        
        "입력값으로 설정될 초기값을 문자열로 설정합니다.",
        "dataType 속성에 관계없이 initValue 속성값으로 입력값이 설정됩니다.",
        "InputBox 컴포넌트가 Group 컴포넌트의 자식일때 Group 컴포넌트의 init() 메소드를 실행하면 InputBox 컴포넌트가 초기화되며 initValue 속성값이 입력값으로 설정됩니다.",
        "InputBox 컴포넌트가 DataMap 과 바인딩 되었다면 화면 렌더링 시 DataMap 에 initValue 값이 반영됩니다.",
        "InputBox 컴포넌트가 DataList 와 바인딩 되었다면 화면 렌더링 시 initValue 값은 무시됩니다.",
        "화면 렌더링 과정에서 통신 요청으로 DataCollection 에 데이터가 로드되면 initValue 값은 표시되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text_display = function(target) {    
    let rtn = '';
    let tagName = target.render.tagName

    if (tagName !== "INPUT") {
        rtn = target.render.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.render.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



// target1
scwin.btn_getText1_onclick = function (e) {
    scwin.get_text_display(target1);
};


// target2
scwin.btn_getText2_onclick = function (e) {
    scwin.get_text_display(target2);
};


// target3
scwin.btn_init_onclick = function (e) {
    group1.init();
};

scwin.btn_getText3_onclick = function (e) {
    scwin.get_text_display(target3);
};


scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("change value");
};


// target4
scwin.btn_getBindDataMap_onclick = function (e) {
    let rtn = '';
    rtn = dm_ref.get("key1");

    wf_body_bottom.getObj("scwin").setReturnValue("bind value : " + rtn);   
};


// target5
scwin.btn_selectData_onclick = function (e) {
    dlt_ref.setRowPosition(1);
};

scwin.btn_getBindDataList_onclick = function (e) {
    let rtn = '';
    rtn = dlt_ref.getRowData(1)

    wf_body_bottom.getObj("scwin").setReturnValue("bind value : " + rtn[0]);       
};


// target6
scwin.btn_smReq_onclick = function (e) {
    $p.executeSubmission("sm_getData");  
};

scwin.sm_getData_submitdone = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("통신 성공 : PASS PASS PASS PASS");  
    dlt_reqData.setRowPosition(1);
}

scwin.sm_getData_submiterror = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("통신 실패 : FAIL FAIL FAIL FAIL");  
};

scwin.btn_getReqDataList_onclick = function (e) {
    let rtn = '';
    rtn = dlt_reqData.getRowData(1)

    wf_body_bottom.getObj("scwin").setReturnValue("bind value : " + rtn[0]);      
};
